{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Trazodone absolute oral bioavailability averaged 70-90% across four subject groups in an IV-comparison study, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Alprazolam absolute oral bioavailability averaged 80-100% after single 1 mg oral doses in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Flibanserin absolute oral bioavailability was estimated at 45.9% from an IV-comparison population PK model, the lowest quantitative value among the evidence set but still above 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved quantitative oral bioavailability records exceed the 20% threshold, with most absolute values ranging from about 33-100%. The lowest well-supported absolute value is flibanserin at 33-46%, still clearly above 20%, so the prediction is high.",
  "evidence_gaps": [
    "Some records are qualitative or from special populations, but quantitative healthy-subject absolute bioavailability values are sufficient for the threshold decision.",
    "Dose and formulation vary across records, but the consistency of values above 20% limits the impact of this variability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

